"""API 2 reference shared by the generated website pages."""
from html import escape
from pathlib import Path
import json


def chapter(ru):
    t = lambda a,b: a if ru else b
    example = json.loads((Path(__file__).resolve().parents[1]/'examples/frontier/mod.json').read_text(encoding='utf-8'))
    rows = [
        ('changes', t('Частичный объект баланса. Указывайте только меняемые поля из справочника. Массивы базовых войск содержат 3 значения. Поздний мод выигрывает для одинакового поля; остальные поля сохраняются. Инспектор показывает источник и перекрытия.', 'Partial balance object. Specify only changed reference fields. Built-in troop arrays contain 3 values. Later mods win for overlapping fields; other fields remain. The inspector shows sources and overlaps.')),
        ('content.units[]', t('До 13 новых родов войск (16 всего). id, name, cost, weight, recruit обязательны; start=0, requires=[] по умолчанию. Целые cost/weight/recruit ≥1, start ≥0. Встроенные ID: infantry, aircraft, navy; новые добавляются после них. requires — ID изученных технологий, открывающих найм и улучшения.', 'Up to 13 new branches (16 total). Required: id, name, cost, weight, recruit; defaults: start=0, requires=[]. Integer cost/weight/recruit ≥1, start ≥0. Built-in IDs: infantry, aircraft, navy; new entries follow them. requires lists technologies unlocking recruitment/upgrades.')),
        ('content.buildings[]', t('До 32 типов. id, name, cost ≥1, income ≥0; requires=[]. Строятся только на своей территории. Цена следующего уровня = cost × (уровень+1), доход = income × уровень. До 1 000 000 уровней; захват сохраняет постройки.', 'Up to 32 types. id, name, cost ≥1, income ≥0; requires=[]. Build only on owned territories. Next level costs cost × (level+1); income is income × level. Up to 1,000,000 levels; conquest preserves buildings.')),
        ('content.technologies[]', t('До 32 разовых исследований. id, name, cost ≥1; requires=[] должны ссылаться на более ранние технологии. unit=infantry, bonus=0 (0..1), income=0. bonus прибавляется к множителю силы указанного рода войск; income — общий дополнительный доход за секунду. В интерфейсе доступны рядом с обычными улучшениями.', 'Up to 32 one-time technologies. id, name, cost ≥1; requires=[] must reference earlier technologies. Defaults: unit=infantry, bonus=0 (0..1), income=0. bonus adds to the selected branch strength multiplier; income adds global income per second. Available alongside regular upgrades.')),
        ('content.map[]', t('Полная замена карты, 3..512 стран, ID подряд с 0. Поля: id, name (RU), english, continent, center:[долгота,широта], rings:[полигон,...], neighbors:[ID,...], sovereign:ID, dependencies:[], enclave_hosts:[]. Координаты ±180/±90, 3..2000 точек в полигоне, до 64 полигонов и 10 000 точек на страну. Границы взаимны; ссылки в пределах карты. Пустой enclave_hosts означает обычную видимую страну. Новый нейтральный гарнизон [18,3,0,...], предприятие уровня 1.', 'Complete map replacement: 3..512 contiguous IDs starting at 0. Fields: id, name (RU), english, continent, center:[longitude,latitude], rings:[polygon,...], neighbors:[ID,...], sovereign:ID, dependencies:[], enclave_hosts:[]. Coordinates ±180/±90; 3..2000 points/polygon, up to 64 polygons and 10,000 points/country. Borders must be mutual; references stay within the map. Empty enclave_hosts means a regular visible country. New neutral garrisons are [18,3,0,...] with one level-1 business.')),
        ('content.scenario', t('name, default_home:ID, starts:{"ID":{coins,units,levels,owned:[ID],researches:[techID]}}, armies:{"ID":[гарнизон]}, alliances:[[ID,ID],...]. Все поля необязательны. units/levels/armies имеют длину общего числа войск; levels ≥1. owned добавляется к домашней стране. Стартовые владения разных стран не пересекаются и не включают скрытые микрогосударства. Союзы — непересекающиеся группы домашних стран, запрещающие взаимные атаки; владения союзников не объединяются.', 'Optional fields: name, default_home:ID, starts:{"ID":{coins,units,levels,owned:[ID],researches:[techID]}}, armies:{"ID":[garrison]}, alliances:[[ID,ID],...]. Troop arrays match the total branch count; levels ≥1. owned supplements the home country. Starting territories cannot overlap or include hidden microstates. Alliances are disjoint groups of home countries preventing mutual attacks; ownership remains separate.')),
        ('content.victory', t('type: world (обычный захват мира), coins + amount ≥1, countries + countries:[ID], hold + countries:[ID] + seconds ≥1, time + seconds ≥1. hold требует непрерывного владения, потеря сбрасывает таймер. Время игровое. Цель заменяет обычную победу; потеря всех территорий остаётся поражением.', 'type: world (default world conquest), coins + amount ≥1, countries + countries:[ID], hold + countries:[ID] + seconds ≥1, time + seconds ≥1. hold requires uninterrupted ownership and resets on loss. Time is simulation time. Custom objectives replace world conquest; losing every territory still ends in defeat.')),
        ('content.events[]', t('До 128 событий. id, when, actions обязательны; once=true, cooldown=1 (игровые секунды). when: start, tick, country_captured, research_completed, building_built, mission_completed. События исполняются по порядку отдельно для каждой фракции. До 16 действий на событие и 64 на один вызов триггера, без рекурсивных вызовов. При исчерпании бюджета оставшиеся события этого вызова откладываются до следующего подходящего триггера.', 'Up to 128 events. Required: id, when, actions; defaults: once=true, cooldown=1 game second. Triggers: start, tick, country_captured, research_completed, building_built, mission_completed. Events run in order per faction. Up to 16 actions/event and 64 per trigger invocation, without recursion. Events beyond that budget wait for the next matching trigger.')),
        ('events[].conditions', t('Все указанные условия соединяются И: country_id (страна триггера), elapsed_min, coins_min, owns:[ID], researches:[techID], flags:{ключ:значение}, chance=100 (целое 0..100). start/research_completed используют домашнюю страну; разведка, захват и строительство — целевую. Для tick не задавайте country_id. Шанс использует отдельный сохраняемый детерминированный генератор и одинаков в Godot/PHP.', 'All supplied conditions combine with AND: country_id (trigger country), elapsed_min, coins_min, owns:[ID], researches:[techID], flags:{key:value}, chance=100 (integer 0..100). start/research_completed use the home country; reconnaissance/conquest/construction use the target. Omit country_id for tick. Chance uses a separate saved deterministic generator shared by Godot/PHP.')),
        ('events[].actions[]', t('type и поля по типу: add_coins {amount}; add_units {unit,amount}; show_message {text}; set_flag {key,value}; grant_research {technology}; capture_country/release_country {country_id}; win/lose без дополнительных полей. amount целый ±1 000 000; unit=infantry. Текст до 400 символов. Флаги: bool или целое ±1 000 000, до 128 уникальных ключей. Действия захвата/выдачи исследований не создают новые триггеры, не дают боевую добычу и не проверяют стоимость исследования. Скрипты и произвольный доступ к файлам отсутствуют.', 'type and fields: add_coins {amount}; add_units {unit,amount}; show_message {text}; set_flag {key,value}; grant_research {technology}; capture_country/release_country {country_id}; win/lose require no extra fields. amount: integer ±1,000,000; unit defaults to infantry. Text ≤400 characters. Flags: bool or integer ±1,000,000, ≤128 distinct keys. Capture/research rewards do not recursively trigger events, award combat loot or charge research prices. No scripts or arbitrary filesystem access.')),
        ('content.translations', t('{"ru":{"исходный текст":"перевод"},"en":{...}}, до 512 записей на язык, ключ/значение до 1024 символов. Заменяются только точные ключи; сохраняйте плейсхолдеры %s/%d и переносы. Стандартный fallback игры действует для отсутствующих ключей.', '{"ru":{"source text":"translation"},"en":{...}}, up to 512 entries/locale, keys/values ≤1024 characters. Exact-key replacement; preserve %s/%d placeholders and newlines. Missing keys use normal game fallback.')),
        ('content.theme', t('Необязательные цвета HTML: ink (текст), muted (вторичный текст), accent (акцент), ocean (океан), unknown (неразведанные земли). Например {"accent":"#f2cf70"}. Проверяйте контраст и видимость фокуса.', 'Optional HTML colors: ink (text), muted (secondary text), accent, ocean, unknown (unexplored land). Example: {"accent":"#f2cf70"}. Check contrast and visible focus.')),
        ('content.assets', t('Объект ключ → {mime,data}. flag:ID — PNG image/png до 1024×1024; sound:CUE — WAV audio/wav, заменяющий стандартный звуковой сигнал. data — канонический base64. До 64 ресурсов, до 192 КиБ декодированных данных на ресурс. Суммарный манифест до 4 МиБ. Ресурсы передаются внутри одного .atlasmod; PNG/WAV декодируются клиентом, PHP их не исполняет.', 'Object key → {mime,data}. flag:ID: PNG image/png up to 1024×1024; sound:CUE: WAV audio/wav replacing a standard cue. data is canonical base64. Up to 64 resources, 192 KiB decoded bytes/resource, 4 MiB total manifest. Resources travel inside the same .atlasmod; clients decode PNG/WAV, PHP does not execute them.')),
        ('content.panels[]', t('До 16 панелей: id, title (до 160 символов), text (до 1024), action="". Отображаются в карточке армии. action открывает army, economy, countries или notifications. Это текст и стандартные кнопки без HTML/JavaScript.', 'Up to 16 panels: id, title (≤160 characters), text (≤1024), action="". Displayed in the army card. action opens army, economy, countries or notifications. Text and standard buttons without HTML/JavaScript.')),
    ]
    intro = t('Используйте API 2 для новых модов. Поля манифеста ID/версия/зависимости остаются прежними; pck_sha256 добавляется сборщиком. changes и content необязательны. ID содержат строчные латинские буквы, цифры, _ и -, до 64 символов. Цена и доход — целые; неизвестные поля контента отклоняются. Каталоги объединяются по порядку модов, повторяющиеся ID отклоняются. scenario, victory и map позднего мода заменяют объект целиком; theme/assets/переводы объединяются по ключам.', 'Use API 2 for new mods. Identity/version/dependency fields are unchanged; builders add pck_sha256. changes and content are optional. IDs use lowercase ASCII letters, digits, _ and -, up to 64 characters. Costs/income are integers; unknown content fields are rejected. Catalogs append in mod order; duplicate IDs fail validation. Later scenario, victory and map objects replace earlier ones; theme/assets/translations merge by key.')
    link = 'mod-studio.ru.html' if ru else 'mod-studio.html'
    result = f'<p>{intro}</p><p><a href="{link}">{t("Открыть редактор модов →","Open mod editor →")}</a></p><div class="table-scroll" tabindex="0"><table><thead><tr><th>JSON</th><th>{t("Описание","Description")}</th></tr></thead><tbody>'
    result += ''.join(f'<tr><td><code>{key}</code></td><td>{description}</td></tr>' for key,description in rows) + '</tbody></table></div>'
    result += '<p><a href="examples/frontier.atlasmod" download>Frontier.atlasmod ↓</a></p><h3>'+t('Рабочий пример Frontier','Working Frontier example')+'</h3><pre><code>'+escape(json.dumps(example,ensure_ascii=False,indent=2))+'</code></pre>'
    result += '<h3>'+t('Сборка и инструменты','Build and tools')+'</h3><pre><code>godot --headless --path . --script tools/build_mod.gd -- examples/frontier dist/frontier.atlasmod\ngodot --headless --path . --script tools/mod_tool.gd -- validate dist/frontier.atlasmod\ngodot --headless --path . --script tools/mod_tool.gd -- inspect dist/frontier.atlasmod\ngodot --headless --path . --script tools/mod_tool.gd -- save-check dist/frontier.atlasmod campaign.json</code></pre>'
    result += '<p>'+t('В игре: Моды → Инструменты модов. Видны итоговые значения, источник каждого изменения и перекрытия. Проверка пакета проверяет добавление к текущему набору; проверка сохранения ничего не записывает. Тестовая кампания сохраняет текущую и создаёт отдельную новую; в сетевой комнате сначала выйдите из неё. Сохранения разделяются по точному отпечатку пакетов. Автоматическая миграция при изменении модов не выполняется: возвращайте исходный набор. Для зависимостей валидируйте весь упорядоченный профиль; отдельный пакет с внешними ссылками не является самостоятельным сценарием.', 'In game: Mods → Mod tools. Inspect final values, each change source and overlaps. Package validation checks addition to the current set; save validation writes nothing. A test campaign saves the current one and creates a separate campaign; leave a network room first. Saves are separated by exact package fingerprints. Changed mod sets are not migrated automatically: restore the original set. Validate the full ordered profile for dependencies; a package with external references is not a standalone scenario.')+'</p>'
    result += '<p>'+t('SDK включает исходник Frontier. Старые три примера API 1 сохранены для совместимости. Мод API 2 без files/ автоматически получает пустой PCK. Редактор сайта создаёт такой пакет для нового проекта и сохраняет исходный PCK при импорте API 2. Экспорт браузера не заменяет полную проверку компилятора SDK.', 'The SDK includes Frontier sources. The three API 1 examples remain for compatibility. API 2 mods without files/ receive an empty PCK automatically. The website editor creates this format for new projects and preserves the original PCK when importing API 2. Browser export does not replace full SDK compiler validation.')+'</p>'
    from mod_workbench_docs import chapter as workbench
    return result + workbench(ru)
